// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonAdmin) public {
        vm.assume(nonAdmin != address(0));
        vm.assume(nonAdmin != address(this));
        address deployer = address(this);
        vm.prank(deployer);
        address originalOwner = c.owner();
        vm.prank(nonAdmin);
        bool ok = true;
        try c.setOwner(address(0x1234)) { ok = true; }
        catch { ok = false; }
        assertTrue(ok == false, "Non-admin must revert on setOwner");
    }
}
